  1: ['1', 'mon', 'monday'],
  2: ['2', 'tue', 'tues', 'tuesday'],
  3: ['3', 'wed', 'wednesday'],
  4: ['4', 'thu', 'thur', 'thurs', 'thursday'],
  5: ['5', 'fri', 'friday'],
  6: ['6', 'sat', 'saturday']
