  const hasWhyChooseUs = visibleWhyChooseUs.length > 0;
  const hasContactRows = visibleContactRows.length > 0;
  const desktopColumns = hasWhyChooseUs ? '1fr 1.6fr 0.92fr' : '1fr 1.6fr';
